def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A vertical 5-bar extends the adjacent bottom color swatch upward.
    used = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] != 5 or (r, c) in used:
                continue
            top = r
            while top > 0 and g[top - 1][c] == 5:
                top -= 1
            bottom = r
            while bottom + 1 < h and g[bottom + 1][c] == 5:
                bottom += 1
            if bottom > top:
                used.update((rr, c) for rr in range(top, bottom + 1))
                if c + 1 < w:
                    # The swatch abuts the lower end of the bar; retain its
                    # full multi-row period and repeat it toward the top.
                    start = bottom
                    while start > top and any(g[start - 1][cc] for cc in range(c + 1, w)):
                        start -= 1
                    tile = [g[rr][c + 1:w] for rr in range(start, bottom + 1)]
                    if any(v for row in tile for v in row):
                        for rr in range(top, bottom + 1):
                            src = tile[(rr - start) % len(tile)]
                            for cc, value in enumerate(src, c + 1):
                                if value:
                                    g[rr][cc] = value

    # A horizontal 5-bar extends the adjacent left-end color swatch across
    # the bar's span, retaining the vertical period of that swatch.
    used = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] != 5 or (r, c) in used:
                continue
            left = c
            while left > 0 and g[r][left - 1] == 5:
                left -= 1
            right = c
            while right + 1 < w and g[r][right + 1] == 5:
                right += 1
            if right > left:
                used.update((r, cc) for cc in range(left, right + 1))
                start = r + 1
                end = start
                while end < h and g[end][left] != 0:
                    end += 1
                tile = [g[rr][left] for rr in range(start, end)]
                if tile:
                    for cc in range(left, right + 1):
                        for k, value in enumerate(tile):
                            if value:
                                g[start + k][cc] = value
    return g
